// Test-only subset used by context-paging tool schemas.
const optional = Symbol("optional");

function schema(type, options = {}) {
	return { ...options, type };
}

export const Type = {
	String(options) {
		return schema("string", options);
	},
	Integer(options) {
		return schema("integer", options);
	},
	Boolean(options) {
		return schema("boolean", options);
	},
	Array(items, options) {
		return { ...options, type: "array", items };
	},
	Optional(value) {
		Object.defineProperty(value, optional, { value: true });
		return value;
	},
	Object(properties, options) {
		const required = Object.entries(properties)
			.filter(([, value]) => !value[optional])
			.map(([name]) => name);
		return {
			...options,
			type: "object",
			properties,
			...(required.length > 0 ? { required } : {}),
		};
	},
};
